-- Esquema aislado de pruebas; nunca ejecutar en una base existente.
do $$ begin
  if current_database() <> 'gym_test' then raise exception 'Solo se permite la base gym_test'; end if;
  if not exists (select from pg_roles where rolname='anon') then create role anon; end if;
  if not exists (select from pg_roles where rolname='authenticated') then create role authenticated; end if;
  if not exists (select from pg_roles where rolname='service_role') then create role service_role; end if;
end $$;
drop schema public cascade; create schema public; grant usage on schema public to service_role, anon, authenticated;
create table public."PLANES_MEMBRESIA" ("id_PM" bigint generated by default as identity primary key, "Nombre_Plan" text, "Duración" text, "Precio" numeric, "descripcion" text, "beneficios" text, "Activo" boolean);
create table public."PROMOCIONES" ("id_promocion" bigint generated by default as identity primary key, "nombre" text, "descripcion" text, "tipo_descuento" text, "valor_descuento" numeric, "fecha_inicio" text, "fecha_fin" text, "activo" boolean, "planes_aplicables" jsonb);
create table public."CLIENTES" ("id_cliente" bigint generated by default as identity primary key, "Nombres" text, "Apellidos" text, "DNI" text, "Telefono" text, "Email" text, "Correo" text, "Fecha_Registro" text, "Estado" boolean, "Plan" text, "password_hash" text, "google_sub" text, "origen_registro" text);
create table public."MEMBRESIA" ("id_membresia" bigint generated by default as identity primary key, "Fecha_Inicio" text, "Fecha_Fin" text, "Estado" text, "id_cliente" bigint, "id_PM" bigint, "monto_pago" numeric, "estado_pago" text, "metodo_pago" text, "referencia_pago" text, "fecha_pago" text);
create table public."USUARIO" ("id_usuario" bigint generated by default as identity primary key, "Nombre" text, "Correo" text, "Telefono" text, "DNI" text, "Contraseña" text, "google_sub" text, "Rol" text, "Estado" boolean);
create table public."INVENTARIO" ("id_item" bigint generated by default as identity primary key, "Nombre_item" text, "Tipo" text, "Cantidad_Stock_E" bigint, "Estado" text, "N_ACTIVO" bigint);
create table public."TIENDA_PRODUCTOS" ("id_producto" bigint generated by default as identity primary key, "id_item" bigint, "nombre_Producto" text, "categoria" text, "precio_Venta" numeric, "cantidad_stock" bigint, "stock_minimo" bigint, "imagen_url" text);
create table public."CATALOGO_RUTINA" ("id_rutina" bigint generated by default as identity primary key, "servicio" text, "Nombre_rutina" text, "Zonas_musculares" text, "Color" text, "ejercicios" jsonb);
create table public."HORARIO" ("id_horario" bigint generated by default as identity primary key, "id_cliente" bigint, "id_rutina" bigint, "Dia_semana" text, "Hora_inicio" text, "Hora_fin" text);
create table public."HORARIOS_SERVICIO" ("id_horario_servicio" bigint generated by default as identity primary key, "servicio" text, "id_rutina" bigint, "codigo_dia" text, "dia" text, "hora_inicio" text, "hora_fin" text, "cupos" bigint, "activo" boolean);
create table public."MATRICULAS_HORARIO" ("id_matricula" bigint generated by default as identity primary key, "id_cliente" bigint, "id_horario_servicio" bigint, "id_rutina" bigint, "fecha_matricula" text, "estado" text);
create table public."RUTINA_PROGRESO" ("id_progreso" bigint generated by default as identity primary key, "id_matricula" bigint, "id_rutina" bigint, "fecha" text, "estado" text, "observacion" text, "id_usuario" bigint, "ejercicios_detalle" jsonb);
create table public."MOV_INV" ("id_mov" bigint generated by default as identity primary key, "id_item" bigint, "id_usuario" bigint, "tipo_movimiento" text, "fecha_movimiento" text, "descripcion" text, "cantidad" bigint, "destino" text);
create table public."TICKETS_ATENCION" ("id_ticket" bigint generated by default as identity primary key, "id_cliente" bigint, "id_usuario" bigint, "tipo_ticket" text, "descripcion" text, "estado_ticket" text, "fecha_emitido" text, "fecha_cierre" text);
create table public."ASISTENCIA" ("id_asistencia" bigint generated by default as identity primary key, "id_cliente" bigint, "id_membresia" bigint, "Fecha" text, "Hora" text, "Validación" boolean, "servicio" text, "id_usuario_registra" bigint, "id_matricula" bigint, "id_horario_servicio" bigint, "hora_entrada" text, "hora_salida" text, "fecha_salida" text, "anulado" boolean, "auditoria" jsonb, "version" bigint);
create table public."VENTAS" ("id_venta" bigint generated by default as identity primary key, "id_cliente" bigint, "cliente_nombre" text, "cliente_correo" text, "cliente_dni" text, "Fecha_Venta" text, "total_Venta" numeric, "metodo_Pago" text, "referencia_pago" text, "estado_pedido" text, "estado_pago" text, "observacion_admin" text, "fecha_actualizacion" text);
create table public."DETALLE_VENTA" ("id_detalle" bigint generated by default as identity primary key, "id_venta" bigint, "id_producto" bigint, "Cantidad" bigint, "Precio_Unitario" numeric, "Subtotal" numeric);
create table public."CONFIGURACION_GIMNASIO" ("id_config" bigint generated by default as identity primary key, "capacidad_total" bigint, "capacidad_por_hora" bigint);
alter table public."DETALLE_VENTA" add foreign key (id_venta) references public."VENTAS" (id_venta);
alter table public."INVENTARIO" add check ("Cantidad_Stock_E" >= 0);
grant select, insert, update, delete on all tables in schema public to service_role;
grant usage, select, update on all sequences in schema public to service_role;
